#!/usr/bin/env node
// OTR-India Anchal module — self-extracting setup script.
// Run with: node setup.js
// Creates the full project structure in the current directory.
const fs = require('fs');
const path = require('path');

const files = {};
files['README.md'] = '';
files['package.json'] = '';
files['src/app.js'] = '';
files['src/controllers/applicationController.js'] = '';
files['src/controllers/consentController.js'] = '';
files['src/controllers/credentialController.js'] = '';
files['src/routes/applicationRoutes.js'] = '';
files['src/routes/consentRoutes.js'] = '';
files['src/routes/credentialRoutes.js'] = '';
files['src/server.js'] = '';
files['src/services/applicationService.js'] = '';
files['src/services/authorizationService.js'] = '';
files['src/services/consentService.js'] = '';
files['src/services/credentialService.js'] = '';
files['src/services/mockIssuer.js'] = '';
files['src/utils/audit.js'] = '';
files['src/utils/ids.js'] = '';
files['src/utils/respond.js'] = '';
files['src/utils/store.js'] = '';
files['tests/api.smoke.test.js'] = '';
files['tests/application.test.js'] = '';
files['tests/authorization.test.js'] = '';
files['tests/consent.test.js'] = '';
files['tests/credential.test.js'] = '';
files['tests/security.test.js'] = '';

for (const [relPath, b64] of Object.entries(files)) {
  const fullPath = path.join(__dirname, relPath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, Buffer.from(b64, 'base64'));
  console.log('created', relPath);
}

console.log('\nDone. Next steps:');
console.log('  npm install');
console.log('  npm test');
console.log('  npm start');